#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor downsample_bilinear_custom_impl_npu(const at::Tensor& self) {
    TORCH_CHECK(self.dim() == 4, "Input must be 4D NCHW");
    auto sizes = self.sizes().vec();
    // Output size fixed to (60, 80) on H, W
    sizes[2] = 60;
    sizes[3] = 80;
    at::Tensor result = at::empty(sizes, self.options());
    EXEC_NPU_CMD(aclnnDownsampleBilinearCustom, self, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("downsample_bilinear_custom", &downsample_bilinear_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("downsample_bilinear_custom", &downsample_bilinear_custom_impl_npu, "Bilinear downsample to (60, 80)");
}
